def split_csv(line):
    fields = []
    i = 0
    n = len(line)
    if n == 0:
        return [""]
    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            field_chars = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i+1] == '"':
                        field_chars.append('"')
                        i += 2
                        continue
                    else:
                        # closing quote
                        i += 1
                        closed = True
                        break
                else:
                    field_chars.append(c)
                    i += 1
            if not closed:
                return None
            # after closing quote must be comma or end of line
            if i < n:
                if line[i] != ',':
                    return None
                i += 1
                fields.append(''.join(field_chars))
                if i == n:
                    fields.append("")
                    return fields
                continue
            else:
                fields.append(''.join(field_chars))
                return fields
        else:
            # unquoted field
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    return None
                i += 1
            fields.append(line[start:i])
            if i == n:
                return fields
            else:
                i += 1
                if i == n:
                    fields.append("")
                    return fields
                continue

